<script setup>
import{ref,computed}from'vue'
const props=defineProps({mass:{type:Number,default:90}}),selected=ref(null),names=['Bremsstrahlung','Non-resonant','Resonant'],colors=['139,175,224','206,171,110','229,139,145']
const benchmarks={
 50:{rows:[[.00386,.000456,.000550],[.0000819,.00439,.000605],[.0000800,.00438,.0299]],produced:[.00605,.0116,.0351],totals:[.00403,.00923,.0311]},
 90:{rows:[[.000850,.000111,.000142],[.0389,1.74,.114],[.00156,.0870,.601]],produced:[.00137,1.96,.705],totals:[.0413,1.82,.715]}
}
const data=computed(()=>benchmarks[props.mass]||benchmarks[90]),rows=computed(()=>data.value.rows),produced=computed(()=>data.value.produced),maximum=computed(()=>Math.max(...rows.value.flat()))
const fmt=n=>n.toPrecision(3),share=(r,c)=>100*rows.value[r][c]/rows.value.reduce((s,row)=>s+row[c],0)
</script><template><div class="matrix-layout"><div class="matrix"><span/><b v-for="c in 3">SR{{c}}</b><template v-for="(row,r) in rows"><strong :style="{color:`rgb(${colors[r]})`}">{{names[r]}}</strong><button v-for="(n,c) in row" :style="{background:`rgba(${colors[r]},${.08+.60*Math.sqrt(n/maximum)})`}" @mouseenter="selected={r,c,n}" @focus="selected={r,c,n}" @mouseleave="selected=null" @blur="selected=null"><span>{{fmt(n)}}</span><small>{{share(r,c).toFixed(share(r,c)&lt;.1?3:1)}}% of SR{{c+1}}</small></button></template><strong>Total</strong><b v-for="n in data.totals" class="total">{{n}}</b></div><aside><div class="eyebrow">Production → selected signal</div><h2>{{selected?names[selected.r]+' → SR'+(selected.c+1):mass===50?'Mixed origins in SR2':'Annihilation dominates at 90 MeV'}}</h2><p v-if="selected"><strong>{{fmt(selected.n)}}</strong> selected events<br/>from {{produced[selected.r]}} produced.<br/><span style="font-size:14px">{{share(selected.r,selected.c).toFixed(2)}}% of this region’s signal.</span></p><p v-else>Cell values: expected selected events.<br/>Percentages: composition within each SR.</p><p v-if="mass===50" class="small muted">SR2: 47.6% non-resonant<br/>and 47.5% resonant.<br/>SR1: ≈96% bremsstrahlung.<br/>SR3: ≈96% resonant.</p><p v-else class="small muted">Non-resonant: ≈95% of SR2.<br/>Resonant: ≈84% of SR3.<br/>Bremsstrahlung is negligible here.</p></aside></div></template><style scoped>.matrix-layout{display:grid;grid-template-columns:2fr 1fr;gap:38px;margin-top:22px}.matrix{align-self:start;grid-template-rows:24px repeat(3,76px) 30px;display:grid;grid-template-columns:145px repeat(3,1fr);gap:5px;align-items:center}.matrix>b{text-align:center;font-size:16px}.matrix>strong{font-size:15px;font-weight:500}.matrix button{height:76px;border:1px solid #ffffff20;border-radius:3px;color:#edf1f7;cursor:pointer;transition:all .3s}.matrix button:hover,.matrix button:focus{outline:2px solid #ceab6e;transform:translateY(-2px)}button span{font-size:23px;display:block}button small{font-size:10px;opacity:.7}.total{padding-top:12px;color:#ceab6e}aside{border-left:2px solid #ceab6e65;padding:15px 0 10px 22px;background:linear-gradient(90deg,#ceab6e08,transparent);border-radius:0 8px 8px 0}aside p{font-size:15px;line-height:1.45}aside h2{font-size:18px}aside strong{font-size:32px;color:#ceab6e}</style>
